Answering the question with an efficient solution in C.

### Método

Para cada string $S_k$, ela é substring da concatenação $S_a S_b$ (com $a, b < k$) se e somente se:
- $S_k$ é substring de $S_a$ ou de $S_b$, ou
- Existe algum $L$ ($1 \le L < |S_k|$) tal que o prefixo de $S_k$ de tamanho $L$ é um **sufixo** de alguma string anterior $S_a$, e o sufixo de $S_k$ de tamanho $|S_k| - L$ é um **prefixo** de alguma string anterior $S_b$.

Como $a$ e $b$ podem ser escolhidos independentemente dentre os índices anteriores a $k$, podemos manter conjuntos (usando uma tabela hash ou trie) de:
1. Todos os prefixos de todas as strings anteriores;
2. Todos os sufixos de todas as strings anteriores;
3. Todas as strings anteriores inteiras (ou substrings).

Para cada string $S_k$, verificamos primeiro se ela já pode ser formada por algum par anterior. Se sim, encontramos a resposta e paramos. Caso contrário, inserimos todos os prefixos e sufixos de $S_k$ nas estruturas e continuamos para $S_{k+1}$.

```c
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <stdlib.h>

#define MAXN 10005
#define HASH_SIZE 1000003

typedef struct Node {
    unsigned long long hash;
    int len;
    struct Node* next;
} Node;

Node* head_pref[HASH_SIZE];
Node* head_suff[HASH_SIZE];

Node node_pool[MAXN * 25];
int pool_ptr = 0;

static inline unsigned long long compute_hash(const char *s, int len) {
    unsigned long long h = 0;
    for (int i = 0; i < len; i++) {
        h = h * 131ULL + (s[i] - 'a' + 1);
    }
    return h;
}

static inline void insert_hash(Node** table, unsigned long long h, int len) {
    int idx = h % HASH_SIZE;
    for (Node* curr = table[idx]; curr != NULL; curr = curr->next) {
        if (curr->hash == h && curr->len == len) return;
    }
    Node* new_node = &node_pool[pool_ptr++];
    new_node->hash = h;
    new_node->len = len;
    new_node->next = table[idx];
    table[idx] = new_node;
}

static inline bool contains_hash(Node** table, unsigned long long h, int len) {
    int idx = h % HASH_SIZE;
    for (Node* curr = table[idx]; curr != NULL; curr = curr->next) {
        if (curr->hash == h && curr->len == len) return true;
    }
    return false;
}

char S[MAXN][32];

int main() {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    for (int i = 0; i < N; i++) {
        scanf("%s", S[i]);
    }

    for (int k = 0; k < N; k++) {
        int m = strlen(S[k]);
        bool found = false;

        if (k > 0) {
            // Verificar se Sk é substring de Sa Sb
            // Caso 1: Sk é exatamente igual a alguma string anterior
            unsigned long long full_h = compute_hash(S[k], m);
            if (contains_hash(head_pref, full_h, m)) {
                found = true;
            }

            // Caso 2: Sk é dividida em um sufixo de Sa e prefixo de Sb
            if (!found) {
                for (int L = 1; L < m; L++) {
                    unsigned long long pref_h = compute_hash(S[k], L);
                    unsigned long long suff_h = compute_hash(S[k] + L, m - L);

                    // O prefixo de Sk (tamanho L) deve ser sufixo de algum Sa
                    // O sufixo de Sk (tamanho m - L) deve ser prefixo de algum Sb
                    if (contains_hash(head_suff, pref_h, L) && contains_hash(head_pref, suff_h, m - L)) {
                        found = true;
                        break;
                    }
                }
            }
        }

        if (found) {
            printf("%s\n", S[k]);
            return 0;
        }

        // Adicionar todos os prefixos e sufixos de S[k] às tabelas
        for (int len = 1; len <= m; len++) {
            unsigned long long p_h = compute_hash(S[k], len);
            insert_hash(head_pref, p_h, len);

            unsigned long long s_h = compute_hash(S[k] + m - len, len);
            insert_hash(head_suff, s_h, len);
        }
    }

    printf("ok\n");
    return 0;
}
