Para resolver este problema de forma eficiente, podemos analisar as propriedades da condição de uma string $S_k$ ser substring de uma concatenação $S_a S_b$ ($a, b < k$):

1. **Substring completa de uma string anterior**: $S_k$ está totalmente contida em $S_a$ ou em $S_b$.
2. **Dividida entre duas strings**: $S_k$ pode ser dividida em um prefixo $P$ não-vazio e um sufixo $Q$ não-vazio ($S_k = P + Q$) de modo que $P$ é sufixo de $S_a$ e $Q$ é prefixo de $S_b$.

Como as strings têm comprimento de até 10 letras minúsculas:
- Cada string ou substring pode ser codificada bijetivamente (sem colisões) em um inteiro de 64 bits (`uint64_t`), pois em base 27, $27^{10} \approx 2.05 \times 10^{14} < 2^{64}$.
- Mantemos uma tabela hash rápida com endereçamento aberto para rastrear os **prefixos**, **sufixos** e **substrings** de todas as strings vistas até o momento.
- Para cada string $S_k$, verificamos primeiro se ela invalida o código. Caso contrário, adicionamos suas partes à tabela hash e continuamos.

Abaixo está a solução completa em C:

```c
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

#define HASH_SIZE (1 << 21) // ~2.09 milhões de posições
#define MASK (HASH_SIZE - 1)

#define FLAG_PREFIX    1
#define FLAG_SUFFIX    2
#define FLAG_SUBSTRING 4

typedef struct {
    uint64_t key;
    uint8_t flags;
    bool occupied;
} HashEntry;

static HashEntry table[HASH_SIZE];

static inline uint64_t murmur64(uint64_t h) {
    h ^= h >> 33;
    h *= 0xff51afd7ed558ccdULL;
    h ^= h >> 33;
    h *= 0xc4ceb9fe1a85ec53ULL;
    h ^= h >> 33;
    return h;
}

static inline void insert(uint64_t key, uint8_t flag) {
    uint32_t idx = (uint32_t)(murmur64(key) & MASK);
    while (table[idx].occupied) {
        if (table[idx].key == key) {
            table[idx].flags |= flag;
            return;
        }
        idx = (idx + 1) & MASK;
    }
    table[idx].occupied = true;
    table[idx].key = key;
    table[idx].flags = flag;
}

static inline uint8_t query(uint64_t key) {
    uint32_t idx = (uint32_t)(murmur64(key) & MASK);
    while (table[idx].occupied) {
        if (table[idx].key == key) {
            return table[idx].flags;
        }
        idx = (idx + 1) & MASK;
    }
    return 0;
}

static inline uint64_t encode(const char *s, int len) {
    uint64_t val = 0;
    for (int i = 0; i < len; i++) {
        val = val * 27 + (s[i] - 'a' + 1);
    }
    return val;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    char s[105];
    int invalid_idx = -1;
    char invalid_str[105] = "";

    for (int k = 1; k <= n; k++) {
        if (scanf("%s", s) != 1) break;
        int len = strlen(s);

        if (invalid_idx == -1) {
            bool is_invalid = false;
            uint64_t full_key = encode(s, len);

            // 1. Verifica se S_k é uma substring completa de alguma string anterior
            if (query(full_key) & FLAG_SUBSTRING) {
                is_invalid = true;
            }

            // 2. Verifica se S_k pode ser particionada em P + Q tal que
            // P é sufixo de S_a e Q é prefixo de S_b
            if (!is_invalid) {
                for (int i = 1; i < len; i++) {
                    uint64_t p_key = encode(s, i);
                    uint64_t q_key = encode(s + i, len - i);

                    if ((query(p_key) & FLAG_SUFFIX) && (query(q_key) & FLAG_PREFIX)) {
                        is_invalid = true;
                        break;
                    }
                }
            }

            if (is_invalid) {
                invalid_idx = k;
                strcpy(invalid_str, s);
            } else {
                // Adiciona todos os prefixos
                for (int i = 1; i <= len; i++) {
                    insert(encode(s, i), FLAG_PREFIX);
                }

                // Adiciona todos os sufixos
                for (int i = 0; i < len; i++) {
                    insert(encode(s + i, len - i), FLAG_SUFFIX);
                }

                // Adiciona todas as substrings
                for (int i = 0; i < len; i++) {
                    for (int l = 1; i + l <= len; l++) {
                        insert(encode(s + i, l), FLAG_SUBSTRING);
                    }
                }
            }
        }
    }

    if (invalid_idx != -1) {
        printf("%s\n", invalid_str);
    } else {
        printf("ok\n");
    }

    return 0;
}
